{
  return q.getDataSource() instanceof QueryDataSource
         && q.context().getBoolean(GroupByQueryConfig.CTX_KEY_FORCE_PUSH_DOWN_NESTED_QUERY, false)
         && q.getSubtotalsSpec() == null;
}

